<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\Repositories\WPDBRepositories\ExamPaymentLinkRepository; use Inc\Repositories\WPDBRepositories\ExamManualResolutionRepository; class ExamPaymentService { private ExamPaymentLinkRepository $paymentRepo; private ExamManualResolutionRepository $resolutionRepo; public function __construct( ?ExamPaymentLinkRepository $paymentRepo = null, ?ExamManualResolutionRepository $resolutionRepo = null ) { $this->paymentRepo = $paymentRepo ?? new ExamPaymentLinkRepository(); $this->resolutionRepo = $resolutionRepo ?? new ExamManualResolutionRepository(); } public function linkGuestApplicationToOrder( int $applicationId, int $wcOrderId, int $wcOrderItemId, int $productId, string $amount ): int { return $this->paymentRepo->insert( [ 'application_id' => $applicationId, 'wc_order_id' => $wcOrderId, 'wc_order_item_id' => $wcOrderItemId, 'product_id' => $productId, 'amount' => $amount, 'payment_state' => 'pending', 'created_at' => current_time( 'mysql', true ), ] ); } public function updatePaymentState( int $paymentLinkId, string $state ): bool { return $this->paymentRepo->update( $paymentLinkId, [ 'payment_state' => $state, 'last_reconciled_at' => current_time( 'mysql', true ), ] ); } public function recordManualResolution( ?int $applicationId, ?int $participationId, string $kind, string $reason, int $actorUserId, ?string $amount = null ): int { return $this->resolutionRepo->insert( [ 'application_id' => $applicationId, 'participation_id' => $participationId, 'kind' => $kind, 'reason' => $reason, 'actor_user_id' => $actorUserId, 'amount' => $amount, 'created_at' => current_time( 'mysql', true ), ] ); } }
